 */
static void test_backoff_progression(void)
{
    /* 显式零初始化退避配置与状态结构体，避免未初始化栈内存告警 */
    backoff_config_t cfg = {0U, 0U, 0U, 0U, 0U};
    cfg.initial_interval_ms = 500U;
    cfg.max_interval_ms = 3000U;
    cfg.multiplier_num = 2U;
    cfg.multiplier_den = 1U;
    cfg.max_retries = 4U;

    backoff_state_t st = {0U, 0U, 0ULL, false};
    assert(backoff_init(&st, &cfg) == LIFECYCLE_OK);

    uint32_t delay = 0U;
    /* 第 1 次重试：返回初始间隔 500 ms，下一次间隔倍增为 1000 ms */
    assert(backoff_next_delay(&st, &cfg, &delay) == LIFECYCLE_OK);
    assert(delay == 500U);
    assert(st.retry_count == 1U);

    /* 第 2 次重试：返回 1000 ms，下一次间隔倍增为 2000 ms */
    assert(backoff_next_delay(&st, &cfg, &delay) == LIFECYCLE_OK);
    assert(delay == 1000U);
    assert(st.retry_count == 2U);

    /* 第 3 次重试：返回 2000 ms，下一次间隔按上限 3000 ms 封顶 */
    assert(backoff_next_delay(&st, &cfg, &delay) == LIFECYCLE_OK);
    assert(delay == 2000U);
    assert(st.retry_count == 3U);

    /* 第 4 次重试：返回封顶值 3000 ms，达到最大重试次数 max_retries = 4 并置位耗尽标志 */
    assert(backoff_next_delay(&st, &cfg, &delay) == LIFECYCLE_OK);
    assert(delay == 3000U);
    assert(st.retry_count == 4U);
    assert(st.is_exhausted == true);

    /* 第 5 次重试：已达上限，返回 LIFECYCLE_ERR_EXHAUSTED 且输出延迟清零 */
    assert(backoff_next_delay(&st, &cfg, &delay) == LIFECYCLE_ERR_EXHAUSTED);
    assert(delay == 0U);

    bool is_ex = false;
    assert(backoff_is_exhausted(&st, &cfg, &is_ex) == LIFECYCLE_OK);
    assert(is_ex == true);

    printf("PASS: test_backoff_progression\n");
